#include "rftd2_private.h"
#include "nvram.h"
#include "nvfs_usr.h"
#include "dbg.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

static Boolean init_table (void) ;


/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
Boolean rftd2_init_nvfs (void)
{
  return init_table() ;
}

//--------------------------------------------------------------------------//

static Boolean init_table (void)
{
  static Rftd2_Entry cur_entry ;
  UInt16 size = 0 ;

	if ((nvfs_rd_size(nvfs_rftd2_entry , &size) == NVFS_OK))
	{
	  if((size == sizeof(cur_entry)) && (nvfs_rd_s(nvfs_rftd2_entry , &rftd2_entry, sizeof(rftd2_entry)) == NVFS_OK))
	  {
		  #if DBG_RFTD2 == 1
		  	  dbg_tx_text ("\n nvfs_rftd2_entry correct read") ;
		  #endif
		  return (TRUE) ;
	  }
	}

  nvfs_delete(nvfs_rftd2_entry) ;
	
  switch (nvfs_wr_create(nvfs_rftd2_entry, &cur_entry , sizeof(Rftd2_Entry)))
    {
      case NVFS_OK :  
        {
		  #if DBG_RFTD2 == 1
        	dbg_tx_text ("\n nvfs_rftd2_entry re-create") ;
		  #endif
          return init_table() ;
        }  
    }      

  return FALSE ;
}

